  ("Nhận ra", 5, ["LI1"], "85mm close-up", "@Linh narrows her eyes, recognising something.", [("Linh", "Khoan. Anh là anh lái xe tuyến đêm à?", "suspicious|nghi ngờ")], "",
   "Cận. Linh nheo mắt, nhận ra."),
  ("Biết tên chưa", 5, ["LI1"], "50mm medium shot", "@Linh crosses her arms.", [("Linh", "Hai năm lái xe, anh biết tên người ta chưa?", "arms crossed|khoanh tay")], "",
   "Trung. Linh khoanh tay."),
